export { findOrder, ORDERS } from './data/orders.js';
export { findCustomer, CUSTOMERS } from './data/customers.js';
export { triageTicket } from './triage.js';

input.command:
node -e "
import { triageTicket } from './src/index.js';
import { scriptedModel } from './test/helpers/mock-model.js';

console.log('Test 1: Normal triage with tool call');
const model1 = scriptedModel([
  { toolCalls: [{ name: 'getCustomer', input: { customerId: 'C1' } }] },
  { text: JSON.stringify({ category: 'billing', priority: 'high', reply: 'We will help you.' }) },
]);
const result1 = await triageTicket(model1, { customerId: 'C1', text: 'Help!' });
console.log('✓ Result:', result1.category, result1.priority);

console.log('\nTest 2: Invalid category should be rejected');
const model2 = scriptedModel([
  { toolCalls: [{ name: 'getCustomer', input: { customerId: 'C2' } }] },
  { text: JSON.stringify({ category: 'invalid', priority: 'low', reply: 'Test' }) },
]);
try {
  await triageTicket(model2, { customerId: 'C2', text: 'Help' });
  console.log('✗ Should have rejected invalid category');
} catch (e) {
  console.log('✓ Properly rejected invalid category');
}

console.log('\nTest 3: Invalid priority should be rejected');
const model3 = scriptedModel([
  { toolCalls: [{ name: 'getCustomer', input: { customerId: 'C1' } }] },
  { text: JSON.stringify({ category: 'bug', priority: 'urgent', reply: 'Test' }) },
]);
try {
  await triageTicket(model3, { customerId: 'C1', text: 'Bug!' });
  console.log('✗ Should have rejected invalid priority');
} catch (e) {
  console.log('✓ Properly rejected invalid priority');
}

console.log('\nTest 4: Model can call customer lookup tool');
const model4 = scriptedModel([
  { toolCalls: [{ name: 'getCustomer', input: { customerId: 'C1' } }] },
  { text: JSON.stringify({ category: 'shipping', priority: 'normal', reply: 'Order coming soon' }) },
]);
const result4 = await triageTicket(model4, { customerId: 'C1', text: 'Where is my order?' });
console.log('✓ Tool call processed, result:', result4.category);

console.log('\nAll tests passed!');
"

